 33→/**
 34→ * Make sure tensor t's data lies completely within ((char)t.data_ptr()) +
 35→ * t.numel() * t.element_size(). This is slightly weaker than t.is_contiguous()
 36→ * because it allows transpose of contiguous slice (i.e. slicing the first
 37→ * dimension). Currently, we require this because stride information is not
 38→ * passed into the kernels and we treat input tensors as flat.
 39→ *
 40→ * Examples
 41→ * A = torch.zeros(3, 3, 3)
 42→ * 1. A: OK
 43→ * 2. A[1:]: OK
 44→ * 3. A.permute(2, 0, 1): OK
 45→ * 4. A[1:].permute(2, 0, 1): OK
 46→ * 5. A[None].expand(2, -1, -1, -1): Not OK
 47→ * 6. A[:, 1:, 1:]: Not OK
 48→ */
 49→bool _is_weak_contiguous(torch::Tensor& t) {
 50→  return t.is_contiguous() ||
 51→         (t.storage().nbytes() - t.storage_offset() * t.element_size() ==
 52→          t.numel() * t.element_size());
 53→}
