 55→/**
 56→ * Performs an out-of-place allreduce and stores result in out.
 57→ *
 58→ * If _reg_buffer is null, assumes inp.data_ptr() is already IPC-registered.
 59→ * Otherwise, _reg_buffer is assumed to be IPC-registered and inp is first
 60→ * copied into _reg_buffer.
 61→ */
 62→void all_reduce(fptr_t _fa, torch::Tensor& inp, torch::Tensor& out,
 63→                fptr_t _reg_buffer, int64_t reg_buffer_sz_bytes) {
 64→  auto fa = reinterpret_cast<vllm::CustomAllreduce*>(_fa);
 65→  const at::cuda::OptionalCUDAGuard device_guard(device_of(inp));
 66→  auto stream = c10::cuda::getCurrentCUDAStream().stream();
 67→
 68→  TORCH_CHECK_EQ(inp.scalar_type(), out.scalar_type());
 69→  TORCH_CHECK_EQ(inp.numel(), out.numel());
 70→  TORCH_CHECK(_is_weak_contiguous(out));
 71→  TORCH_CHECK(_is_weak_contiguous(inp));
 72→  auto input_size = inp.numel() * inp.element_size();
 73→  auto reg_buffer = reinterpret_cast<void*>(_reg_buffer);
 74→  if (reg_buffer) {
 75→    TORCH_CHECK_LE(input_size, reg_buffer_sz_bytes);
 76→    AT_CUDA_CHECK(cudaMemcpyAsync(reg_buffer, inp.data_ptr(), input_size,
 77→                                  cudaMemcpyDeviceToDevice, stream));
 78→  } else {
 79→    reg_buffer = inp.data_ptr();
 80→  }
 81→  switch (out.scalar_type()) {
 82→    case at::ScalarType::Float: {
 83→      fa->allreduce<float>(stream, reinterpret_cast<float*>(reg_buffer),
 84→                           reinterpret_cast<float*>(out.data_ptr()),
 85→                           out.numel());
 86→      break;
 87→    }
 88→    case at::ScalarType::Half: {
 89→      fa->allreduce<half>(stream, reinterpret_cast<half*>(reg_buffer),
 90→                          reinterpret_cast<half*>(out.data_ptr()), out.numel());
 91→      break;
 92→    }
 93→#if (__CUDA_ARCH__ >= 800 || !defined(__CUDA_ARCH__))
 94→    case at::ScalarType::BFloat16: {
 95→      fa->allreduce<nv_bfloat16>(
 96→          stream, reinterpret_cast<nv_bfloat16*>(reg_buffer),
 97→          reinterpret_cast<nv_bfloat16*>(out.data_ptr()), out.numel());
 98→      break;
 99→    }
100→#endif

