 28→// Activation and gating kernel template.
 29→template <typename scalar_t, typename packed_t,
 30→          scalar_t (*ACT_FN)(const scalar_t&),
 31→          packed_t (*PACKED_ACT_FN)(const packed_t&), bool act_first,
 32→          bool use_vec, bool use_256b = false>
 33→__global__ void act_and_mul_kernel(
 34→    scalar_t* __restrict__ out,          // [..., d]
 35→    const scalar_t* __restrict__ input,  // [..., 2, d]
 36→    const int d) {
 37→  const scalar_t* x_ptr = input + blockIdx.x * 2 * d;
 38→  const scalar_t* y_ptr = x_ptr + d;
 39→  scalar_t* out_ptr = out + blockIdx.x * d;
 40→
 41→  if constexpr (use_vec) {
 42→    using cuda_t = typename CUDATypeConverter<scalar_t>::Type;
 43→    using pvec_t = PackedVec<cuda_t, use_256b>;
 44→
 45→    const pvec_t* x_vec = reinterpret_cast<const pvec_t*>(x_ptr);
 46→    const pvec_t* y_vec = reinterpret_cast<const pvec_t*>(y_ptr);
 47→    pvec_t* out_vec = reinterpret_cast<pvec_t*>(out_ptr);
 48→    const int num_vecs = d / 2 / pvec_t::NUM_ELTS;
 49→
 50→    for (int i = threadIdx.x; i < num_vecs; i += blockDim.x) {
 51→      pvec_t x, y;
 52→      if constexpr (use_256b) {
 53→        ld256(x, &x_vec[i]);
 54→        ld256(y, &y_vec[i]);
 55→      } else {
 56→        ld128(x, &x_vec[i]);
 57→        ld128(y, &y_vec[i]);
 58→      }
 59→#pragma unroll
 60→      for (int j = 0; j < pvec_t::NUM_ELTS; j++) {
 61→        x.elts[j] = packed_compute<packed_t, PACKED_ACT_FN, act_first>(
 62→            x.elts[j], y.elts[j]);
 63→      }
 64→      if constexpr (use_256b) {
 65→        st256(x, &out_vec[i]);
 66→      } else {
 67→        st128(x, &out_vec[i]);
 68→      }
 69→    }
 70→  } else {
 71→    // Scalar fallback for unaligned data or small d
 72→    for (int64_t idx = threadIdx.x; idx < d; idx += blockDim.x) {
 73→      const scalar_t x = VLLM_LDG(&x_ptr[idx]);
 74→      const scalar_t y = VLLM_LDG(&y_ptr[idx]);
 75→      out_ptr[idx] = compute<scalar_t, ACT_FN, act_first>(x, y);
 76→    }
 77→  }
 78→}
