 35→void swap_blocks(torch::Tensor& src, torch::Tensor& dst,
 36→                 int64_t block_size_in_bytes,
 37→                 const torch::Tensor& block_mapping) {
 38→  torch::Device src_device = src.device();
 39→  torch::Device dst_device = dst.device();
 40→  cudaMemcpyKind memcpy_type;
 41→  if (src_device.is_cuda() && dst_device.is_cuda()) {
 42→    TORCH_CHECK(src_device.index() == dst_device.index(),
 43→                "src and dst must be on the same GPU");
 44→    memcpy_type = cudaMemcpyDeviceToDevice;
 45→  } else if (src_device.is_cuda() && dst_device.is_cpu()) {
 46→    memcpy_type = cudaMemcpyDeviceToHost;
 47→  } else if (src_device.is_cpu() && dst_device.is_cuda()) {
 48→    memcpy_type = cudaMemcpyHostToDevice;
 49→  } else {
 50→    TORCH_CHECK(false, "Invalid device combination");
 51→  }
 52→
 53→  // NOTE(youkaichao): keep in mind that `block_mapping` should be
 54→  // a cpu tensor, otherwise every `item` call will require a gpu-cpu
 55→  // synchronization.
 56→  TORCH_CHECK(block_mapping.device().is_cpu(), "block_mapping must be on CPU");
 57→
 58→  char* src_ptr = static_cast<char*>(src.data_ptr());
 59→  char* dst_ptr = static_cast<char*>(dst.data_ptr());
 60→
 61→  const at::cuda::OptionalCUDAGuard device_guard(
 62→      src_device.is_cuda() ? src_device : dst_device);
 63→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
 64→  // NOTE(woosuk): This can be slow if the number of blocks is large.
 65→  const int64_t num_blocks = block_mapping.size(0);
 66→  for (size_t i = 0; i < num_blocks; i++) {
 67→    int64_t src_block_number = block_mapping[i][0].item<int64_t>();
 68→    int64_t dst_block_number = block_mapping[i][1].item<int64_t>();
 69→    int64_t src_offset = src_block_number * block_size_in_bytes;
 70→    int64_t dst_offset = dst_block_number * block_size_in_bytes;
 71→    cudaMemcpyAsync(dst_ptr + dst_offset, src_ptr + src_offset,
 72→                    block_size_in_bytes, memcpy_type, stream);
 73→  }
 74→}
