 78→// Grid: (num_layers, num_pairs)
 79→template <typename scalar_t>
 80→__global__ void copy_blocks_kernel(int64_t* key_cache_ptrs,
 81→                                   int64_t* value_cache_ptrs,
 82→                                   const int64_t* __restrict__ block_mapping,
 83→                                   const int numel_per_block) {
 84→  const int layer_idx = blockIdx.x;
 85→  const int pair_idx = blockIdx.y;
 86→
 87→  scalar_t* key_cache = reinterpret_cast<scalar_t*>(key_cache_ptrs[layer_idx]);
 88→  scalar_t* value_cache =
 89→      reinterpret_cast<scalar_t*>(value_cache_ptrs[layer_idx]);
 90→  int64_t src_block_number = block_mapping[2 * pair_idx];
 91→  int64_t dst_block_number = block_mapping[2 * pair_idx + 1];
 92→
 93→  const int64_t src_block_offset = src_block_number * numel_per_block;
 94→  const int64_t dst_block_offset = dst_block_number * numel_per_block;
 95→  for (int i = threadIdx.x; i < numel_per_block; i += blockDim.x) {
 96→    int64_t src_offset = src_block_offset + i;
 97→    int64_t dst_offset = dst_block_offset + i;
 98→    key_cache[dst_offset] = key_cache[src_offset];
 99→  }
100→  for (int i = threadIdx.x; i < numel_per_block; i += blockDim.x) {
101→    int64_t src_offset = src_block_offset + i;
102→    int64_t dst_offset = dst_block_offset + i;
103→    value_cache[dst_offset] = value_cache[src_offset];
104→  }
105→}
